diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/MACDIndicator.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/MACDIndicator.java
index 5a0b3e443..fd7a46769 100644
--- a/ta4j-core/src/main/java/org/ta4j/core/indicators/MACDIndicator.java
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/MACDIndicator.java
@@ -26,0 +27 @@ import org.ta4j.core.Indicator;
+import org.ta4j.core.indicators.numeric.NumericIndicator;
@@ -85,0 +87,16 @@ public class MACDIndicator extends CachedIndicator<Num> {
+    /**
+     * @param barCount of signal line
+     * @return signal line for this MACD indicator
+     */
+    public EMAIndicator getSignalLine(int barCount) {
+        return new EMAIndicator(this, barCount);
+    }
+
+    /**
+     * @param barCount of signal line
+     * @return histogram of this MACD indicator
+     */
+    public NumericIndicator getHistogram(int barCount) {
+        return NumericIndicator.of(this).minus(getSignalLine(barCount));
+    }
+
